let started=false,wordChosen=false,initialOpen=false,flashWord=null,showComparison=false,fitPending=false;
let imageScale=1,viewCenter={x:.5,y:.5},initialFeelings=[],initialFindings=[],detailChoices=[[],[],[]],wholeFeelings=[],correctionIndex=0;
let feelingsByWord={};let extraFinding='';let firstFinding='',detailOwn=['','','',''],detailFeelings=[[],[],[],[]];
function emotionKey(){return window.classroom?.draftKey?window.classroom.draftKey+':emotion':'zhangfa-emotion-v6'}
function loadEmotionDraft(){
 let entry={};try{entry=JSON.parse(localStorage.getItem(emotionKey())||'null')||{}}catch{}
 ({initialFeelings=[],initialFindings=[],detailChoices=[[],[],[]],wholeFeelings=[],firstFeel='',firstFinding='',laterFeel='',detailOwn=['','','',''],detailFeelings=[[],[],[],[]],extraFinding='',feelingsByWord={}}=entry);
 initialOpen=false;showComparison=false;
}
loadEmotionDraft();
const moodWords=['平静','沉重','急切','激动','复杂','杂乱','悲痛','有力量'];
function emotionSave(){try{localStorage.setItem(emotionKey(),JSON.stringify({initialFeelings,initialFindings,detailChoices,wholeFeelings,firstFeel,firstFinding,laterFeel,detailOwn,detailFeelings,extraFinding,feelingsByWord}))}catch{}}
function words(items,type,values){return `<div class="choices">${items.map(t=>`<button data-pick="${type}" data-value="${t}" aria-pressed="${values.includes(t)}">${t}</button>`).join('')}</div>`}
