function activeCues(){if(specialStep!==1||spot<0)return [];return detailChoices[spot].includes(flashWord)?(observationCues[flashWord]||[]):[]}
function cueOverlay(){return activeCues().map(c=>`<g class="observation-cue"><rect x="${c.box[0]}" y="${c.box[1]}" width="${c.box[2]}" height="${c.box[3]}" rx="3" fill="#ffdb81" fill-opacity=".08" stroke="#bd342e" stroke-width="2"/><text x="${c.box[0]}" y="${c.box[1]-7}" font-size="12" fill="#9c241f" stroke="#fff6da" stroke-width="3" paint-order="stroke">${c.label}</text>${c.gap?`<rect class="spacing-gap" x="${c.gap[0]}" y="${c.gap[1]}" width="${c.gap[2]}" height="${c.gap[3]}" rx="2" fill="#f4ad25" fill-opacity=".7"/>`:''}</g>`).join('')}
