function fitAnnotations(viewport){const cues=activeCues();if(!cues.length)return;const vw=viewport.clientWidth,vh=viewport.clientHeight,W=1536,H=465;if(spot===2&&flashWord==='有多处涂改'){imageScale=1;viewCenter={x:.5,y:.5};return}const x1=Math.min(...cues.map(c=>c.box[0]))-24,y1=Math.min(...cues.map(c=>c.box[1]))-34,x2=Math.max(...cues.map(c=>c.box[0]+c.box[2]))+72,y2=Math.max(...cues.map(c=>c.box[1]+c.box[3]))+24;imageScale=Math.max(1,Math.min(8,(vw-32)*W/(vw*(x2-x1)),(vh-32)*W/(vw*(y2-y1))));viewCenter={x:(x1+x2)/2/W,y:(y1+y2)/2/H}}
